package org.apache.commons.text;

import org.junit.Test;
import static org.junit.Assert.assertNull;
import org.evosuite.runtime.EvoRunner;
import org.evosuite.runtime.EvoRunnerParameters;
import org.junit.runner.RunWith;

@RunWith(EvoRunner.class)
@EvoRunnerParameters(mockJVMNonDeterminism = true, useVFS = true, useVNET = true, resetStaticState = true, separateClassLoader = false)
public class StringTokenizer_ESTest_test11 extends StringTokenizer_ESTest_scaffolding {

    /**
     * A freshly created tokenizer starts positioned before the first token, so
     * there is no previous token to move back to. In that situation
     * {@link StringTokenizer#previousToken()} should return {@code null} rather
     * than throw an exception.
     */
    @Test(timeout = 4000)
    public void previousTokenAtStartReturnsNull() throws Throwable {
        // Input is 10 NUL characters (the default value for a new char[]).
        char[] input = new char[10];
        char delimiter = '(';
        char quote = '�';
        StringTokenizer tokenizer = new StringTokenizer(input, delimiter, quote);

        // The iterator is at the start, so there is no previous token.
        String previousToken = tokenizer.previousToken();

        assertNull(previousToken);
    }
}
